"""Modern implementation of the Meridian order_fulfilment workflow."""

from decimal import Decimal, DecimalException
from typing import Any


def _positive_amount(value: Any) -> bool:
    """Implement the guard: NVL(TOT_AMT, 0) > 0."""
    if value is None or value == "":
        value = 0

    try:
        amount = Decimal(str(value).strip())
        return amount.is_finite() and amount > 0
    except (DecimalException, TypeError, ValueError):
        return False


def _account_on_credit_hold(record: dict, tables: dict) -> bool:
    """Return whether the first matching live account has CRED_HOLD='Y'."""
    account_id = record.get("ACCT_ID", "")

    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "") == "Y"

    return False


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment transition."""
    record_copy = dict(record)

    if state == "E" and event == "approve" and _positive_amount(
        record.get("TOT_AMT", "")
    ):
        return {
            "state": "A",
            "record": record_copy,
            "audits": ["ORD_APPR"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": record_copy,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": record_copy,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if (
        state == "A"
        and event == "cancel"
        and not _account_on_credit_hold(record, tables)
    ):
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
